//! The command table: one [`Command`] per RPC of hostkeeper's non-local
//! services, generated by `build.rs` from the descriptor set (the generator is `ctl_gen.rs`).
//! Nothing here is written by hand but the shapes of the entries; a new RPC in a proto is a new
//! entry of [`COMMANDS`] at the next build.
//!
//! The command line `hkctl` (the crate `hostkeeper-hkctl`) is generated from this table, and the
//! web app's client (`ui/gen/`) too, by `hostkeeper-ui-tests`. This crate stays code generation only.
//!
//! How a request field becomes input ([`Input`]):
//!
//! - a scalar or enum field, singular, `optional` or repeated, and a `map<string, string>`, is a
//!   flag named after the field in kebab case (`node_id` is `--node-id`);
//! - a message field, a member of a `oneof`, a `bytes` field, any other map, and a repeated secret
//!   come only through the request file (`--request`);
//! - a field marked `(hostkeeper.secret)`, singular, is never a flag: it is read from
//!   `--<flag>-file` or `--<flag>-stdin`.

/// One RPC, as `<service_command> <method_command>` names it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Command {
    /// The proto package of the service: `hostkeeper.operator.v1`.
    pub package: &'static str,
    /// The service's name: `Releases`.
    pub service: &'static str,
    /// The RPC's name: `SetDesired`.
    pub method: &'static str,
    /// The gRPC path, which the HTTP/JSON gateway also serves: `/hostkeeper.operator.v1.Releases/SetDesired`.
    pub path: &'static str,
    /// The service's name in kebab case: `releases`.
    pub service_command: &'static str,
    /// The RPC's name in kebab case: `set-desired`.
    pub method_command: &'static str,
    /// The comment before the service in its proto.
    pub service_doc: &'static str,
    /// The comment before the RPC in its proto.
    pub doc: &'static str,
    /// The full name of the request message.
    pub request: &'static str,
    /// The full name of the response message.
    pub response: &'static str,
    /// Every field of the request, as the message declares them.
    pub fields: &'static [Field],
}

/// One field of a request.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Field {
    /// The field's name in the proto: `node_id`.
    pub name: &'static str,
    /// The field's name in kebab case, the flag it is or the stem of its secret flags.
    pub flag: &'static str,
    pub kind: FieldKind,
    /// The full name of the enum or message of an `Enum` or `Message` field; empty otherwise.
    pub type_name: &'static str,
    pub label: Label,
    pub input: Input,
    /// The field carries `(hostkeeper.secret) = true`.
    pub secret: bool,
    /// The values a flag of an enum field takes; empty for every other field.
    pub enum_values: &'static [EnumValue],
    /// The comment before the field in its proto.
    pub doc: &'static str,
}

/// A value an enum flag takes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EnumValue {
    /// The value's name without its enum's prefix, in lower case: `converged`.
    pub flag: &'static str,
    /// The value's name: `CONVERGENCE_STATE_CONVERGED`.
    pub name: &'static str,
    pub number: i32,
}

/// The protobuf type of a field. A map field is a `Message` (its entry) with [`Label::Map`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FieldKind {
    Double,
    Float,
    Int32,
    Int64,
    Uint32,
    Uint64,
    Sint32,
    Sint64,
    Fixed32,
    Fixed64,
    Sfixed32,
    Sfixed64,
    Bool,
    String,
    Bytes,
    Enum,
    Message,
}

/// How many values a field holds, and how its presence is kept.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Label {
    /// One value; for a scalar, absent and the default are the same on the wire.
    Singular,
    /// A proto3 `optional` scalar: absent and the default stay distinct.
    Optional,
    /// Any number of values.
    Repeated,
    /// A map.
    Map,
    /// A member of a `oneof`.
    Oneof,
}

/// Where the value of a field comes from on the command line.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Input {
    /// `--<flag> <value>`, repeated for a repeated field or a map.
    Flag,
    /// A secret: `--<flag>-file <path>` or `--<flag>-stdin`, never a flag value.
    SecretFile,
    /// Only the request file, `--request <file|->`.
    RequestFile,
}

include!(concat!(env!("OUT_DIR"), "/ctl_commands.rs"));
